const {chromium}=require('playwright');const assert=require('assert');
const base='http://127.0.0.1:8080/?participant=050&build=500audit';
const banned=/prototype|p0 readiness|production (system|engine|keneflex brain)|product[- ]intelligence|future commerce|support role|second support|role being completed|still completing|research preview|commercial firewall|re[- ]?solve|keneflex should|treatment value/i;
const stories=[];const regions=['right wrist and thumb','left wrist','right thumb','left shoulder','right knee','left ankle','right heel','left elbow','neck','lower back'];const triggers=['phone and computer use','typing','scrolling','larger movements','stairs','walking','morning walking','gripping and lifting','morning','lifting'];for(let i=0;i<500;i++){const j=i%10;stories.push(`My ${regions[j]} has been sore for ${2+(i%5)} weeks. ${triggers[j]} makes it worse. ${i%3?'No injury.':'It came on gradually.'}`)}
function money(s){return parseFloat(String(s||'').replace(/[^0-9.]/g,''));}
(async()=>{const browser=await chromium.launch({headless:true,channel:'chrome'});const page=await browser.newPage({viewport:{width:390,height:844}});const fail=[];
for(let i=0;i<500;i++){try{
 await page.goto(base+'&case='+(i+1),{waitUntil:'domcontentloaded',timeout:10000});await page.waitForSelector('#opening',{timeout:3000});
 await page.evaluate(story=>{state.opening=story;document.querySelector('#intro')?.classList.add('hidden');document.querySelector('#chatView')?.classList.add('hidden');document.querySelector('#solutionView')?.classList.remove('hidden');if(typeof showSolution==='function')showSolution();window.KFX049?.clean();},stories[i]);await page.waitForTimeout(30);
 let a=await page.evaluate(()=>{const root=document.querySelector('#solutionView');const text=(root?.innerText||'').replace(/\s+/g,' ');const total=document.querySelector('#total')?.textContent?.trim();const buy=document.querySelector('.kfxBuy');const visible=buy&&buy.getClientRects().length>0;const prices=[...document.querySelectorAll('#solutionView .planItem:not(.removed) .price')].map(e=>parseFloat((e.textContent||'').replace(/[^0-9.]/g,''))).filter(Number.isFinite);return{text,total,buy:buy?.textContent||'',visible,sum:prices.reduce((x,y)=>x+y,0)};});
 assert(a.total,'missing total');assert(a.visible,'buy CTA missing/hidden');assert(a.buy.includes(a.total),'buy CTA does not repeat total');const leak=a.text.match(banned);assert(!leak,`internal/development language visible: ${leak?.[0]||'unknown'}`);assert(Math.abs(money(a.total)-a.sum)<.011,`total mismatch ${a.total} vs ${a.sum}`);
 if(i%5===0){const before=money(a.total);const topical=page.locator('[data-tune="topical"]');if(await topical.count()){await topical.click();await page.waitForTimeout(35);const t=await page.evaluate(()=>({removed:document.querySelector('#topicalItem')?.classList.contains('removed'),total:document.querySelector('#total')?.textContent?.trim(),buy:document.querySelector('.kfxBuy')?.textContent||'',headline:document.querySelector('#solutionView .solHero h1')?.textContent||''}));assert(t.removed,'optional topical did not subtract');assert(Math.abs(money(t.total)-(before-11.99))<.02,'subtotal did not update after topical subtraction');assert(t.buy.includes(t.total),'buy CTA did not update after subtraction');assert(/Keneflex recommends/i.test(t.headline),'subtraction replaced the underlying recommendation');a.total=t.total;}}
 if(i%25===1){for(const key of ['how','approach']){await page.click(`[data-modal="${key}"]`);await page.waitForTimeout(20);const m=await page.evaluate(()=>({visible:!document.querySelector('#modal')?.classList.contains('hidden'),text:(document.querySelector('#modalContent')?.innerText||'').replace(/\s+/g,' ')}));assert(m.visible,`${key} modal did not open`);assert(m.text.length>20,`${key} modal empty`);const ml=m.text.match(banned);assert(!ml,`${key} modal leaks internal language: ${ml?.[0]||'unknown'}`);await page.click('#closeModal');}}
 if(i%20===2){const planBtn=page.locator('#kfxVPacketBtn');if(await planBtn.count()){const pp=page.waitForEvent('popup',{timeout:3000});await planBtn.click();const pop=await pp;await pop.waitForLoadState('domcontentloaded');const p=await pop.evaluate(()=>({title:document.title,text:(document.body.innerText||'').replace(/\s+/g,' '),imgs:[...document.images].filter(x=>x.getClientRects().length).length,overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+2}));assert.equal(p.title,'Your Keneflex Plan');const pl=p.text.match(banned);assert(!pl,`Keneflex Plan leaks internal language: ${pl?.[0]||'unknown'}`);assert(p.imgs>=2,'Keneflex Plan lacks premium visual imagery');assert(!p.overflow,'Keneflex Plan horizontally overflows');await pop.close();}}
 await page.click('.kfxBuy');await page.waitForSelector('.kfxCheckoutOverlay',{timeout:2000});const c=await page.evaluate(()=>({text:(document.querySelector('.kfxCheckout')?.innerText||'').replace(/\s+/g,' '),total:document.querySelector('.kfxCheckout .totalx span:last-child')?.textContent?.trim(),final:!!document.querySelector('[data-kfx-final]')}));assert(c.total===a.total,'cart total differs');assert(c.final,'final checkout action missing');const cl=c.text.match(banned);assert(!cl,`cart leaks internal language: ${cl?.[0]||'unknown'}`);await page.click('[data-kfx-final]');await page.waitForSelector('[data-kfx-close2]',{timeout:2000});const finalText=await page.locator('.kfxCheckout').innerText();assert(/Purchase choice recorded/i.test(finalText),'final cart decision did not complete');
 }catch(e){fail.push({subject:i+1,error:e.message});}finally{await page.evaluate(()=>document.querySelector('.kfxCheckoutOverlay')?.remove()).catch(()=>{});} }
await browser.close();console.log(JSON.stringify({subjects:500,failed:fail.length,sample:fail.slice(0,30)},null,2));if(fail.length)process.exit(1);})();
